WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, items, SIZE(items) AS num_items, attributes['gift'] AS gift, AGGREGATE(items, 0.0D, (acc, i) -> acc + i.qty * i.price, acc -> ROUND(acc, 2)) AS cart_value, ARRAY_CONTAINS(coupon_codes, 'VIP') AS used_vip FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'VIP')) SELECT id, created_at, coupon_codes, num_items, gift, cart_value, SUM(cart_value) OVER (PARTITION BY DATE_TRUNC('YEAR', created_at) ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS cart_value_sum_30m, COUNT(cart_value) OVER (PARTITION BY customer_id ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS cart_value_count_15m, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('MONTH', created_at), customer_id ORDER BY cart_value DESC, id) AS row_seq FROM unpacked WHERE cart_value BETWEEN 800 AND 1400;
